CREATE TABLE trigger_stock(id INT PRIMARY KEY, qty INT);
CREATE TRIGGER stock_fill BEFORE INSERT ON trigger_stock
FOR EACH ROW SET NEW.qty=IFNULL(NEW.qty,0);
INSERT INTO trigger_stock VALUES(1,NULL),(2,3);
SELECT id,qty FROM trigger_stock ORDER BY id;

CREATE TABLE trigger_checked(id INT PRIMARY KEY,qty INT,note VARCHAR(20)) ENGINE=InnoDB;
DELIMITER //
CREATE TRIGGER stock_check BEFORE INSERT ON trigger_checked
FOR EACH ROW
BEGIN
 IF NEW.qty<0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='negative stock';
 END IF;
 SET NEW.note=IFNULL(NEW.note,'待盘点');
END//
DELIMITER ;
INSERT INTO trigger_checked VALUES(1,3,NULL);
SELECT id,qty,note FROM trigger_checked;

CREATE TABLE stock_use(id INT PRIMARY KEY,qty INT) ENGINE=InnoDB;
CREATE TABLE stock_log(id INT,old_qty INT,new_qty INT) ENGINE=InnoDB;
INSERT INTO stock_use VALUES(1,5);
DELIMITER //
CREATE TRIGGER stock_audit AFTER UPDATE ON stock_use FOR EACH ROW
BEGIN
 IF NOT(OLD.qty<=>NEW.qty) THEN
  INSERT INTO stock_log VALUES(NEW.id,OLD.qty,NEW.qty);
 END IF;
END//
DELIMITER ;
UPDATE stock_use SET qty=4 WHERE id=1;
SELECT * FROM stock_log;

CREATE TABLE stock_drop(id INT PRIMARY KEY,qty INT);
CREATE TRIGGER drop_fill BEFORE INSERT ON stock_drop
FOR EACH ROW SET NEW.qty=IFNULL(NEW.qty,0);
DROP TRIGGER IF EXISTS drop_fill;
INSERT INTO stock_drop VALUES(1,NULL);
SELECT qty FROM stock_drop WHERE id=1;

CREATE TABLE warehouse(id INT PRIMARY KEY,qty INT) ENGINE=InnoDB;
CREATE TABLE warehouse_audit(item_id INT,old_qty INT,new_qty INT) ENGINE=InnoDB;
INSERT INTO warehouse VALUES(8,10);
CREATE TRIGGER warehouse_changed AFTER UPDATE ON warehouse
FOR EACH ROW INSERT INTO warehouse_audit VALUES(NEW.id,OLD.qty,NEW.qty);
UPDATE warehouse SET qty=qty-2 WHERE id=8;
SELECT item_id,old_qty,new_qty FROM warehouse_audit;

CREATE TABLE trigger_task(id INT PRIMARY KEY,flag INT) ENGINE=InnoDB;
CREATE TABLE task_audit(id INT) ENGINE=InnoDB;
INSERT INTO trigger_task VALUES(1,0),(2,0);
CREATE TRIGGER task_mark AFTER UPDATE ON trigger_task
FOR EACH ROW INSERT INTO task_audit VALUES(NEW.id);
UPDATE trigger_task SET flag=1;
SELECT id FROM task_audit ORDER BY id;
